/// `PlayerInputProfile.CopyKeysFrom(PlayerInputProfile, InputMode, string[])` (PlayerInputProfile.cs:328)
pub unsafe fn copy_keys_from(this: *mut terraria::game_input::player_input_profile::PlayerInputProfile, mut profile: Gc<terraria::game_input::player_input_profile::PlayerInputProfile>, mut mode: i32, mut keysToCopy: Arr<Str>) {
    {
        let mut i: i32 = 0;
        'l1: loop
        {
            rt::yield_point();
            if !((i < keysToCopy.len())) { break 'l1; }
            'c1:
            {
                let mut value: Gc<List<Str>> = rt::zero::<Gc<List<Str>>>();
                if (*(*(*(*profile.ptr()).input_modes.ptr()).get_item(mode).ptr()).key_status.ptr()).try_get_value(rt::wbv((*keysToCopy.at(i))), core::ptr::addr_of_mut!(value))
                {
                    (*(*(*(*(*this).input_modes.ptr()).get_item(mode).ptr()).key_status.ptr()).get_item((*keysToCopy.at(i))).ptr()).clear();
                    (*(*(*(*(*this).input_modes.ptr()).get_item(mode).ptr()).key_status.ptr()).get_item((*keysToCopy.at(i))).ptr()).add_range(rt::wbv(Seq::from_list(value)));
                }
            }
            i = i.wrapping_add(1);
        }
    }
}

